import json
import os
import sys

def format_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    fda_data = {}
    if os.path.exists(fda_file):
        with open(fda_file, "r", encoding="utf-8") as f:
            raw_fda = json.load(f)
            if isinstance(raw_fda, dict) and "results" in raw_fda:
                results = raw_fda["results"]
            elif isinstance(raw_fda, list):
                results = raw_fda
            else:
                results = []

            for item in results:
                rn = item.get("recall_number")
                if rn:
                    rn_str = str(rn).strip()
                    if rn_str not in fda_data:
                        fda_data[rn_str] = []
                    fda_data[rn_str].append(item)

    field_map = {
        "fda.classified_30d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date", True),
            "classification date": ("fda_enforcement_reports", "center_classification_date", True),
        },
        "fda.terminated_180d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date", True),
            "termination date": ("fda_enforcement_reports", "termination_date", True),
        },
    }

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity_id = pair.split("::", 1)
        entity_id = entity_id.strip()
        facts_list = facts_spec.get(rule_id, [])
        output[pair] = {}

        records = fda_data.get(entity_id, [])

        for fact_name in facts_list:
            rule_facts = field_map.get(rule_id, {})
            spec = rule_facts.get(fact_name)
            if not spec:
                output[pair][fact_name] = "ABSENT"
                continue

            doc_name, field_name, is_date = spec

            vals = set()
            for rec in records:
                raw_val = rec.get(field_name)
                if raw_val is not None:
                    raw_val_str = str(raw_val).strip()
                    if raw_val_str != "":
                        if is_date:
                            formatted = format_date(raw_val_str)
                            if formatted:
                                vals.add(formatted)
                        else:
                            vals.add(raw_val_str)

            if len(vals) == 0:
                output[pair][fact_name] = "ABSENT"
            elif len(vals) == 1:
                val = next(iter(vals))
                output[pair][fact_name] = [val, doc_name]
            else:
                output[pair][fact_name] = "CONFLICT"

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

