import sys
import os
import json


def format_date(d_str):
    if d_str is None:
        return None
    d_str = str(d_str).strip()
    if not d_str:
        return None
    if len(d_str) == 8 and d_str.isdigit():
        return f"{d_str[:4]}-{d_str[4:6]}-{d_str[6:]}"
    parts = d_str.replace('/', '-').split('-')
    if len(parts) == 3 and len(parts[0]) == 4 and len(parts[1]) <= 2 and len(parts[2]) <= 2:
        return f"{int(parts[0]):04d}-{int(parts[1]):02d}-{int(parts[2]):02d}"
    return d_str


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    fda_file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall = {}
    if os.path.exists(fda_file_path):
        with open(fda_file_path, "r", encoding="utf-8") as f:
            fda_data = json.load(f)
            if isinstance(fda_data, dict) and "results" in fda_data:
                results = fda_data["results"]
            elif isinstance(fda_data, list):
                results = fda_data
            else:
                results = []

            for item in results:
                recall_num = str(item.get("recall_number", "")).strip()
                if recall_num:
                    records_by_recall.setdefault(recall_num, []).append(item)

    rule_fact_map = {
        ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date"),
        ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date"),
    }

    output = {}

    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::", 1)
        facts_list = manifest.get("facts", {}).get(rule_id, [])

        pair_output = {}
        entity_records = records_by_recall.get(entity.strip(), [])

        for fact_name in facts_list:
            mapping = rule_fact_map.get((rule_id, fact_name))
            if not mapping:
                pair_output[fact_name] = "ABSENT"
                continue

            doc_name, field_name = mapping
            distinct_values = set()

            for rec in entity_records:
                val = rec.get(field_name)
                formatted_val = format_date(val)
                if formatted_val is not None:
                    distinct_values.add(formatted_val)

            if len(distinct_values) == 0:
                pair_output[fact_name] = "ABSENT"
            elif len(distinct_values) == 1:
                pair_output[fact_name] = [next(iter(distinct_values)), doc_name]
            else:
                pair_output[fact_name] = "CONFLICT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

