import json
import os
import sys

FACT_TO_FIELD = {
    "initiation date": "recall_initiation_date",
    "recall initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "center classification date": "center_classification_date",
    "termination date": "termination_date",
    "report date": "report_date",
}


def clean_val(field, val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val == "N/A":
        return None
    if "date" in field:
        if len(val) == 8 and val.isdigit():
            return f"{val[:4]}-{val[4:6]}-{val[6:]}"
        if len(val) == 10 and val[4] == "-" and val[7] == "-":
            return val
    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports.json
    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall = {}
    doc_name = "fda_enforcement_reports"

    if os.path.exists(fda_file):
        with open(fda_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                rec_num = item.get("recall_number")
                if rec_num:
                    records_by_recall.setdefault(rec_num, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_spec.get(rule_id, [])

        pair_result = {}
        matching_records = records_by_recall.get(entity, [])

        for fact in fact_names:
            field = FACT_TO_FIELD.get(fact.strip().lower())
            if not field:
                field = fact.strip().lower().replace(" ", "_")

            values = set()
            for rec in matching_records:
                raw_val = rec.get(field)
                val = clean_val(field, raw_val)
                if val is not None:
                    values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [next(iter(values)), doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

