import sys
import json
import os
from datetime import datetime

FACT_FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date",
    "report date": "report_date",
}

def format_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str or val_str.upper() == "N/A":
        return None
    if len(val_str) == 8 and val_str.isdigit():
        return f"{val_str[:4]}-{val_str[4:6]}-{val_str[6:8]}"
    if len(val_str) == 10 and val_str[4] == '-' and val_str[7] == '-':
        return val_str
    for fmt in ("%Y%m%d", "%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d"):
        try:
            dt = datetime.strptime(val_str, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass
    return val_str

def load_records(packet_dir):
    json_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
