import json
import os
import sys

FACT_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

RULE_FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}


def format_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str or val_str.lower() in ("n/a", "none", "null"):
        return None
    if len(val_str) == 8 and val_str.isdigit():
        return f"{val_str[:4]}-{val_str[4:6]}-{val_str[6:8]}"
    return val_str


def load_enforcement_reports(packet_dir):
    file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    if not os.path.exists(file_path):
        return []
    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, dict):
        return data.get("results", [])
    elif isinstance(data, list):
        return data
    return []


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    reports = load_enforcement_reports(packet_dir)

    # Index reports by recall_number
    by_recall_number = {}
    for r in reports:
        num = r.get("recall_number")
        if num:
            by_recall_number.setdefault(num.strip(), []).append(r)

    results = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()

        rule_facts = facts_by_rule.get(rule_id, [])
        pair_result = {}

        matching_records = by_recall_number.get(entity, [])

        for fact_name in rule_facts:
            mapping = None
            if rule_id in RULE_FACT_MAP and fact_name in RULE_FACT_MAP[rule_id]:
                mapping = RULE_FACT_MAP[rule_id][fact_name]
            elif fact_name in FACT_MAP:
                mapping = FACT_MAP[fact_name]

            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name = mapping
            values = set()

            for rec in matching_records:
                raw_val = rec.get(field_name)
                formatted_val = format_date(raw_val)
                if formatted_val is not None:
                    values.add(formatted_val)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [next(iter(values)), doc_name]

        results[pair] = pair_result

    print(json.dumps(results, indent=1))


if __name__ == "__main__":
    main()

